# Environment variables `just` gives Tofu, resolved from Bitwarden (folder "homelab")
# by `scripts/bw-run --env-map secrets.env.map`. Names only; values never live here.
#
#   ENV_NAME=bitwarden item name
#
# Items named env/<NAME> were copied from the repo-root .env; <state>/<var> items from
# tofu/<state>/terraform.tfvars (variables declared `sensitive = true`), both by
# scripts/secrets-to-bitwarden.py. TF_VAR_* only take effect once the key is removed
# from terraform.tfvars (a tfvars value beats the environment).

# Proxmox API (bpg provider + Ansible dynamic inventory)
PROXMOX_VE_API_TOKEN=env/PROXMOX_VE_API_TOKEN
PROXMOX_TOKEN_SECRET=env/PROXMOX_TOKEN_SECRET
# Authentik provider
AUTHENTIK_TOKEN=env/AUTHENTIK_TOKEN
# Garage S3 backend (Tofu state)
AWS_ACCESS_KEY_ID=env/AWS_ACCESS_KEY_ID
AWS_SECRET_ACCESS_KEY=env/AWS_SECRET_ACCESS_KEY

# tofu/pets sensitive variables
TF_VAR_oidc_client_secrets=pets/oidc_client_secrets
TF_VAR_coder_proxmox_password=pets/coder_proxmox_password
TF_VAR_agentgateway_ui_client_secret=pets/agentgateway_ui_client_secret
